import React, { useState } from 'react';
import './App.css';

function App() {
  // State variables for user inputs
  const [hashrate, setHashrate] = useState('');
  const [powerConsumption, setPowerConsumption] = useState('');
  const [electricityCost, setElectricityCost] = useState('');
  const [bitcoinPrice, setBitcoinPrice] = useState('');
  const [networkDifficulty, setNetworkDifficulty] = useState('');
  
  // State for calculated results
  const [results, setResults] = useState(null);

  const handleSubmit = (e) => {
    e.preventDefault();

    // Parse numeric values
    const hashrateNum = parseFloat(hashrate);           // in TH/s
    const powerNum = parseFloat(powerConsumption);        // in Watts
    const elecCostNum = parseFloat(electricityCost);        // $/kWh
    const btcPriceNum = parseFloat(bitcoinPrice);         // in $
    const difficultyNum = parseFloat(networkDifficulty);  // raw difficulty value

    // Convert hashrate from TH/s to H/s (1 TH/s = 1e12 H/s)
    const hashrateH = hashrateNum * 1e12;

    // Constants for Bitcoin mining
    const blockReward = 6.25;             // BTC per block
    const blocksPerDay = 144;             // ~144 blocks mined per day
    const hashConstant = 4294967296;      // 2^32

    // Calculate the daily Bitcoin produced using:
    // Daily BTC = (hashrate (H/s) / (difficulty * 2^32)) * blockReward * blocksPerDay
    const dailyBTC = (hashrateH / (difficultyNum * hashConstant)) * blockReward * blocksPerDay;

    // Convert BTC mined per day to revenue (USD)
    const dailyRevenue = dailyBTC * btcPriceNum;

    // Calculate daily electricity cost:
    // Convert power consumption from Watts to kW and multiply by 24 hours.
    const powerKW = powerNum / 1000;
    const dailyElecCost = powerKW * 24 * elecCostNum;

    // Estimated profits after subtracting electricity costs
    const dailyProfit = dailyRevenue - dailyElecCost;
    const monthlyProfit = dailyProfit * 30;
    const yearlyProfit = dailyProfit * 365;

    // Update results state with several details
    setResults({
      dailyProfit,
      monthlyProfit,
      yearlyProfit,
      dailyBTC,
      dailyRevenue,
      dailyElecCost
    });
  };

  return (
    <div className="app">
      {/* Header Section */}
      <header className="header">
        <h1>Bitcoin Mining Profitability Calculator</h1>
        <p>
          Estimate your daily, monthly, and yearly profits from Bitcoin mining using your rig’s parameters.
        </p>
      </header>

      {/* Two-column layout: Left for inputs, Right for results */}
      <main className="calculator-container">
        {/* Left Card: Input Form */}
        <section className="card left-card">
          <h2>Enter Mining Parameters</h2>
          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label htmlFor="hashrate">Hashrate (TH/s):</label>
              <input
                id="hashrate"
                type="number"
                placeholder="e.g., 50"
                value={hashrate}
                onChange={(e) => setHashrate(e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label htmlFor="powerConsumption">Power Consumption (Watts):</label>
              <input
                id="powerConsumption"
                type="number"
                placeholder="e.g., 3000"
                value={powerConsumption}
                onChange={(e) => setPowerConsumption(e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label htmlFor="electricityCost">Electricity Cost ($/kWh):</label>
              <input
                id="electricityCost"
                type="number"
                placeholder="e.g., 0.1"
                step="0.01"
                value={electricityCost}
                onChange={(e) => setElectricityCost(e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label htmlFor="bitcoinPrice">Bitcoin Price ($):</label>
              <input
                id="bitcoinPrice"
                type="number"
                placeholder="e.g., 20000"
                value={bitcoinPrice}
                onChange={(e) => setBitcoinPrice(e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label htmlFor="networkDifficulty">Network Difficulty:</label>
              <input
                id="networkDifficulty"
                type="number"
                placeholder="e.g., 25000000000000"
                value={networkDifficulty}
                onChange={(e) => setNetworkDifficulty(e.target.value)}
                required
              />
            </div>
            <button type="submit" className="calculate-btn">Calculate</button>
          </form>
        </section>

        {/* Right Card: Display Results */}
        <section className="card right-card">
          <h2>Results</h2>
          {results ? (
            <div className="results-display">
              <div className="result-item">
                <span>Daily Profit:</span>
                <span>${results.dailyProfit.toFixed(2)}</span>
              </div>
              <div className="result-item">
                <span>Monthly Profit:</span>
                <span>${results.monthlyProfit.toFixed(2)}</span>
              </div>
              <div className="result-item">
                <span>Yearly Profit:</span>
                <span>${results.yearlyProfit.toFixed(2)}</span>
              </div>
              <hr />
              <div className="result-item">
                <span>Daily BTC Mined:</span>
                <span>{results.dailyBTC.toFixed(8)} BTC</span>
              </div>
              <div className="result-item">
                <span>Daily Revenue:</span>
                <span>${results.dailyRevenue.toFixed(2)}</span>
              </div>
              <div className="result-item">
                <span>Electricity Cost/Day:</span>
                <span>${results.dailyElecCost.toFixed(2)}</span>
              </div>
            </div>
          ) : (
            <p>Enter your mining parameters to see estimated profits.</p>
          )}
        </section>
      </main>

      {/* Footer Section */}
      <footer className="footer">
        <p>&copy; {new Date().getFullYear()} Bitcoin Mining Calculator</p>
      </footer>
    </div>
  );
}

export default App;
